// Plain-language reading of one DORIS warning for the "Check before you decide"
// list. A known warning (dorisWarningPatterns, generated by
// scripts/generate_doris_messages.py) gets its meaning and what to do, with the
// code and its ICD-11 title filled in; anything else is shown as DORIS wrote
// it, with TUC, TSP and UCOD spelled out. The Expo app mirrors this in
// mobile/digitva-collect/src/workspace/doris/dorisWarnings.ts;
// tests/fixtures/doris_warning_cases.json is the parity check for both.
'use strict';

import { dorisWarningPatterns } from './doris_messages.js?v=1';

function lines(value) {
  return typeof value === 'string' ? value.split('\n').map(function (line) { return line.trim(); }).filter(Boolean) : [];
}

export function expandAbbreviations(text) {
  return text.replace(/\bTUC\b/g, 'tentative underlying cause')
    .replace(/\bTSP\b/g, 'tentative starting point')
    .replace(/\bUCOD\b/g, 'underlying cause of death');
}

// DORIS warns with a bare rule id ("M4 may have been applied.") and explains
// the rule in its report ("M4: Adding the main injury - NC72.Z - as
// postcoordination for the current TUC - PA60."). Join the two.
function explained(warning, report) {
  var rule = warning.match(/^(SP\d+|M\d+)\b(?!:)/);
  if (!rule) return warning;
  var detail = lines(report).find(function (line) { return line.indexOf(rule[1] + ':') === 0; });
  if (!detail) return warning;
  detail = detail.slice(rule[1].length + 1).trim();
  return warning.replace(/\.$/, '') + ': ' + detail;
}

// The known pattern a warning matches, with its named fields, or null.
function matchWarning(text) {
  for (var i = 0; i < dorisWarningPatterns.length; i += 1) {
    var entry = dorisWarningPatterns[i];
    var match = text.match(new RegExp(entry.pattern));
    if (!match) continue;
    var values = {};
    entry.fields.forEach(function (field, index) { values[field] = match[index + 1] || ''; });
    return {entry: entry, values: values};
  }
  return null;
}

// titleOf(code) -> the ICD-11 title already known for the code, or undefined.
// Returns {text, original, code}: original is DORIS's text when a known pattern
// explained the warning (shown smaller underneath), null otherwise.
export function describeWarning(warning, report, titleOf) {
  var text = typeof warning === 'string' ? warning.trim() : '';
  var known = matchWarning(text);
  if (!known) return {text: expandAbbreviations(explained(text, report)), original: null, code: null};
  var code = known.values.code || '';
  var title = code && titleOf ? titleOf(code) || '' : '';
  var cause = code ? code + (title ? ' (' + title + ')' : '') : '';
  var fill = function (template) {
    return template.replace(/\{cause\}/g, cause).replace(/\{manner\}/g, known.values.manner || '');
  };
  return {text: [fill(known.entry.meaning), fill(known.entry.action)].join(' '), original: text, code: code || null};
}

// The ICD codes the known warnings name, for the caller to look titles up for.
export function warningCodes(warnings) {
  var codes = [];
  lines(warnings).forEach(function (warning) {
    var known = matchWarning(warning);
    var code = known && known.values.code;
    if (code && codes.indexOf(code) === -1) codes.push(code);
  });
  return codes;
}
